#!/bin/bash
# Leaf5: fabric underlay. Generated by Ansible - do not edit by hand.
set -e
nv set system hostname leaf5
nv set interface lo ip address 10.10.10.5/32
nv set interface swp1,swp2,swp3,swp4
nv set router bgp autonomous-system 65105
nv set router bgp router-id 10.10.10.5
nv set vrf default router bgp neighbor swp1 remote-as external
nv set vrf default router bgp neighbor swp2 remote-as external
nv set vrf default router bgp neighbor swp3 remote-as external
nv set vrf default router bgp neighbor swp4 remote-as external
nv set vrf default router bgp address-family ipv4-unicast network 10.10.10.5/32
nv config apply -y
nv config save
